// projectExportRoundTrip.test.mjs — the critical proof for Project Exchange
// v1: a workbook generated by Project Export/Blank Template survives the
// real Import pipeline (parseImportFile -> suggestColumnMapping ->
// applyColumnMapping -> validateProjectImportRow -> planProjectImport)
// byte-for-byte, with ZERO manual column remapping.
//
// Run: node src/export/xlsx/projectExportRoundTrip.test.mjs
import assert from 'node:assert/strict';
import * as XLSX from 'xlsx';
import { buildProjectWorkbook, workbookToArrayBuffer, PROJECTS_SHEET_NAME } from './buildProjectWorkbook.js';
import { PROJECT_EXPORT_HEADERS, buildProjectExportRow } from './projectExportRow.js';
import { parseImportFile } from '../../core/import/parseImportFile.js';
import { suggestColumnMapping, applyColumnMapping } from '../../core/import/projectImportFieldMap.js';
import { validateProjectImportRow } from '../../core/import/validateProjectImportRow.js';
import { planProjectImport } from '../../core/import/planProjectImport.js';

let pass = 0, fail = 0;
function check(label, condition) {
  if (condition) { pass++; console.log(`  OK ${label}`); }
  else           { fail++; console.error(`  FAIL ${label}`); }
}

const MALL_PROJECT = {
  storeCode: 'KZ-EXPORT-MALL', country: 'Kazakhstan', city: 'Almaty',
  locationType: 'Mall', shoppingMallName: 'MEGA Alma-Ata', street: null,
  projectType: 'Rebuilding', storeConcept: 'Flagship',
  storeSizeSqm: 1250, salesAreaSqm: 900, backOfHouseAreaSqm: 350,
  constructionStartDate: '2026-08-01', constructionEndDate: '2026-11-15', targetOpeningDate: '2026-11-21',
  actualConstructionStartDate: '2026-01-10', actualConstructionCompletionDate: '2026-11-15', actualOpeningDate: '2026-11-21',
  budget: 500000, actualCost: 525000, currencyCode: 'KZT',
  generalContractor: 'Acme Build', contractorEmail: 'gc@acme.test',
};

const STREET_PROJECT = {
  storeCode: 'KZ-EXPORT-STREET', country: 'Kazakhstan', city: 'Astana',
  locationType: 'Street', shoppingMallName: null, street: 'Abay Ave 42',
  projectType: 'New Opening', storeConcept: 'Standard',
  storeSizeSqm: 600, salesAreaSqm: 450, backOfHouseAreaSqm: 150,
  constructionStartDate: '2026-03-01', constructionEndDate: '2026-08-01', targetOpeningDate: '2026-09-15',
  actualConstructionStartDate: null, actualConstructionCompletionDate: null, actualOpeningDate: null,
  budget: null, actualCost: null, currencyCode: null,
  generalContractor: null, contractorEmail: null,
};

// ── §21: Export -> Import round-trip (projects already exist -> SKIP is
// expected and correct; the real proof is normalized values matching source
// facts exactly) ────────────────────────────────────────────────────────────
console.log('\nExport -> Import round-trip: normalized values match source facts exactly');
{
  const wb = buildProjectWorkbook([MALL_PROJECT, STREET_PROJECT]);
  const bytes = workbookToArrayBuffer(wb);
  const parsed = parseImportFile({ filename: 'projects.xlsx', data: bytes });
  check('parseImportFile reads the generated workbook successfully', parsed.ok === true);
  check('sheet name is Projects', parsed.sheetName === PROJECTS_SHEET_NAME);
  check('headers match PROJECT_EXPORT_HEADERS exactly', JSON.stringify(parsed.headers) === JSON.stringify(PROJECT_EXPORT_HEADERS));

  const suggestions = suggestColumnMapping(parsed.headers);
  check('every header auto-maps to a canonical field — zero manual remapping needed', suggestions.every(s => s.suggestedField != null));

  const mapping = Object.fromEntries(suggestions.map(s => [s.header, s.suggestedField]));
  const existingProjects = [{ storeCode: 'KZ-EXPORT-MALL' }, { storeCode: 'KZ-EXPORT-STREET' }];
  const plan = planProjectImport({ headers: parsed.headers, rows: parsed.rows, mapping, existingProjects });

  check('planProjectImport succeeds (no mapping conflicts)', plan.ok === true);
  check('both rows are SKIP (projects already exist) — this is correct, not a round-trip failure', plan.rows.every(r => r.action === 'SKIP'));

  const [mallRow, streetRow] = plan.rows;
  check('Mall row: store_code matches', mallRow.normalized.store_code === MALL_PROJECT.storeCode);
  check('Mall row: location_type matches', mallRow.normalized.location_type === 'Mall');
  check('Mall row: shopping_mall_name matches', mallRow.normalized.shopping_mall_name === MALL_PROJECT.shoppingMallName);
  check('Mall row: street is null (Mall/Street mutual exclusivity preserved)', mallRow.normalized.street === null);
  check('Mall row: store_size_sqm matches', mallRow.normalized.store_size_sqm === MALL_PROJECT.storeSizeSqm);
  check('Mall row: sales_area_sqm matches', mallRow.normalized.sales_area_sqm === MALL_PROJECT.salesAreaSqm);
  check('Mall row: back_of_house_area_sqm matches', mallRow.normalized.back_of_house_area_sqm === MALL_PROJECT.backOfHouseAreaSqm);
  check('Mall row: construction_start_date matches', mallRow.normalized.construction_start_date === MALL_PROJECT.constructionStartDate);
  check('Mall row: construction_end_date (Planned Construction End) matches', mallRow.normalized.construction_end_date === MALL_PROJECT.constructionEndDate);
  check('Mall row: target_opening_date matches', mallRow.normalized.target_opening_date === MALL_PROJECT.targetOpeningDate);
  // §12/§26: all three planned dates preserved exactly, in the same batch,
  // with no date swapped between fields.
  check('all three planned dates preserved exactly: Start=2026-08-01, End=2026-11-15, Opening=2026-11-21',
    mallRow.normalized.construction_start_date === '2026-08-01'
    && mallRow.normalized.construction_end_date === '2026-11-15'
    && mallRow.normalized.target_opening_date === '2026-11-21');
  check('construction_end_date is not contaminated by/confused with a forecast field (no such key exists on the normalized row)',
    !('construction_completion_date' in mallRow.normalized) && !('forecast_opening_date' in mallRow.normalized));
  check('Mall row: actual_construction_start_date matches', mallRow.normalized.actual_construction_start_date === MALL_PROJECT.actualConstructionStartDate);
  check('Mall row: actual_construction_completion_date matches', mallRow.normalized.actual_construction_completion_date === MALL_PROJECT.actualConstructionCompletionDate);
  check('Mall row: actual_opening_date matches', mallRow.normalized.actual_opening_date === MALL_PROJECT.actualOpeningDate);
  check('Mall row: budget matches', mallRow.normalized.budget === MALL_PROJECT.budget);
  check('Mall row: actual_cost matches', mallRow.normalized.actual_cost === MALL_PROJECT.actualCost);
  check('Mall row: currency_code (KZT) is recognized, matches, and produces no warning', mallRow.normalized.currency_code === 'KZT'
    && mallRow.warnings.every(w => w.code !== 'UNRECOGNIZED_CURRENCY'));
  check('Mall row: general_contractor matches', mallRow.normalized.general_contractor === MALL_PROJECT.generalContractor);
  check('Mall row: contractor_email matches', mallRow.normalized.contractor_email === MALL_PROJECT.contractorEmail);

  check('Street row: location_type matches', streetRow.normalized.location_type === 'Street');
  check('Street row: shopping_mall_name is null', streetRow.normalized.shopping_mall_name === null);
  check('Street row: street matches', streetRow.normalized.street === STREET_PROJECT.street);
  check('Street row: all-null financial fields stay null, not fabricated zero', streetRow.normalized.budget === null && streetRow.normalized.actual_cost === null);
}

// ── §22: Blank Template certification ───────────────────────────────────────
console.log('\nBlank Template certification');
{
  const wb = buildProjectWorkbook([]); // exact same generator as Export, empty input
  check('Projects sheet exists', wb.SheetNames.length === 1 && wb.SheetNames[0] === PROJECTS_SHEET_NAME);

  const table = XLSX.utils.sheet_to_json(wb.Sheets[PROJECTS_SHEET_NAME], { header: 1, defval: null });
  check('exact canonical headers, exact order', JSON.stringify(table[0]) === JSON.stringify(PROJECT_EXPORT_HEADERS));
  check('zero project data rows', table.length === 1);

  const suggestions = suggestColumnMapping(table[0]);
  check('every header maps deterministically (mapping suggestions), even with zero data rows', suggestions.every(s => s.suggestedField != null));

  // The parser is EXPECTED to reject an actually-empty upload with a clear
  // "no data rows" message — the template itself (headers only) is valid;
  // uploading it unfilled is correctly rejected. Not weakening this on
  // purpose (task §22).
  const bytes = workbookToArrayBuffer(wb);
  const parsed = parseImportFile({ filename: 'template.xlsx', data: bytes });
  check('parser correctly rejects the still-empty template as NO_USABLE_ROWS (not a bug — expected UX)', parsed.ok === false && parsed.error.code === 'NO_USABLE_ROWS');
}

// ── §23: Filled Template certification — download -> fill -> upload works ──
console.log('\nFilled Template certification (Download Template -> fill -> Import)');
{
  const wb = buildProjectWorkbook([]); // the actual blank template a user downloads
  // Simulate a user filling it in a spreadsheet editor: start from the
  // template's own header row and append 2 data rows (via the same row
  // builder Export itself uses — standing in for "the user typed matching
  // values into the template's columns").
  const sheet = wb.Sheets[PROJECTS_SHEET_NAME];
  const existingTable = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: null });
  const filledTable = [
    existingTable[0],
    buildProjectExportRow(MALL_PROJECT),
    buildProjectExportRow(STREET_PROJECT),
  ];

  const filledSheet = XLSX.utils.aoa_to_sheet(filledTable);
  const filledWorkbook = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(filledWorkbook, filledSheet, PROJECTS_SHEET_NAME);
  const filledBytes = XLSX.write(filledWorkbook, { bookType: 'xlsx', type: 'array' });

  const parsed = parseImportFile({ filename: 'filled-template.xlsx', data: filledBytes });
  check('filled template parses successfully', parsed.ok === true);
  check('2 data rows present', parsed.rows.length === 2);

  const suggestions = suggestColumnMapping(parsed.headers);
  check('generated headers auto-map with zero manual remapping', suggestions.every(s => s.suggestedField != null));
  const mapping = Object.fromEntries(suggestions.map(s => [s.header, s.suggestedField]));

  // Fresh, isolated identity set — neither store code exists yet.
  const plan = planProjectImport({ headers: parsed.headers, rows: parsed.rows, mapping, existingProjects: [] });
  check('plan succeeds with no mapping conflicts', plan.ok === true);
  check('both rows resolve to CREATE against a fresh identity set', plan.rows.length === 2 && plan.rows.every(r => r.action === 'CREATE'));
  check('summary reports 2 creates, 0 skip, 0 blocked', plan.summary.create === 2 && plan.summary.skip === 0 && plan.summary.blocked === 0);
}

console.log(`\n-- RESULT: ${pass} passed, ${fail} failed --\n`);
if (fail > 0) process.exit(1);
